import React, { useState, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

const BuyButton = ({ productId, supplierId, price }) => {
    const { user, token } = useContext(AuthContext);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');

    const handleBuy = async () => {
        if (!user || user.role !== 'user') {
            setMessage('Только пользователи могут покупать товары');
            return;
        }

        setLoading(true);
        try {
            const res = await fetch('http://localhost:5000/api/purchases', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify({
                    product: productId,
                    supplier: supplierId,
                    quantity: 1,
                    purchasePrice: price
                })
            });
            const data = await res.json();
            if (data.success) {
                setMessage('Товар успешно куплен!');
                setTimeout(() => setMessage(''), 3000);
            } else {
                setMessage('Ошибка: ' + data.message);
            }
        } catch {
            setMessage('Ошибка подключения');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div>
            <button onClick={handleBuy} disabled={loading}>
                {loading ? 'Покупка...' : 'Купить'}
            </button>
            {message && <p>{message}</p>}
        </div>
    );
};

BuyButton.defaultProps = {
    price: 0
};

export default BuyButton;
